graph.add(
  new GPUSpatialJoinCandidates({
    left: input.parks,
    right: input.tracts,
    spatialContext: input.spatialContext,
    output: input.pairs
  })
);
graph.add(
  new GPUHistogram({
    input: input.pairs.rightIds,
    output: tractMatches,
    domain: [0, tractMatches.length - 1]
  })
);
// tractMatches colours tracts; pairs identify parks and tracts.
